use bevy::prelude::{Commands, MessageReader, Query};

use crate::effects;

/// 611.2a A continuous effect generated by the resolution of a spell or ability lasts as long as
/// stated by the spell or ability creating it (such as "until end of turn").
///
/// 613.4c Power- and/or toughness-changing effects are applied in layer 7c after all other
/// effects in layers 1 through 7b.
pub fn r611_2a_continuous_effects(
    mut modifications: MessageReader<effects::PowerToughnessModified>,
    mut commands: Commands,
    modifiers: Query<&effects::PowerToughnessModifier>,
) {
    for modification in modifications.read() {
        let current = modifiers
            .get(modification.target)
            .copied()
            .unwrap_or_default();
        commands
            .entity(modification.target)
            .insert(effects::PowerToughnessModifier {
                power: current.power.saturating_add(modification.power),
                toughness: current.toughness.saturating_add(modification.toughness),
            });
    }
}

#[cfg(test)]
mod tests {
    use crate::actions;
    use crate::damage;
    use crate::effects;
    use crate::mana;
    use crate::testing::*;
    use crate::{BATTLEFIELD, GRAVEYARD, HAND};

    #[test]
    fn test_usage() {
        let mut game = MockGame::builder()
            .hand(Seat::P1, [giant_growth()])
            .battlefield(Seat::P1, [grizzly_bears()])
            .mana_pool(Seat::P1, mana![G])
            .build();
        let growth = game.find(game.p1, HAND, "Giant Growth").unwrap();
        let bears = game.find(game.p1, BATTLEFIELD, "Grizzly Bears").unwrap();
        game.act(game.p1, actions::Action::Cast(growth));
        game.act(game.p1, actions::Action::ChooseTargets(vec![bears]));
        game.pass_priority_all();
        let modifier = game
            .app
            .world()
            .get::<effects::PowerToughnessModifier>(bears)
            .copied();
        assert_eq!(
            modifier,
            Some(effects::PowerToughnessModifier {
                power: 3,
                toughness: 3,
            })
        );
        assert_eq!(game.zone_of(growth), GRAVEYARD);
    }

    #[test]
    fn r611_2a_giant_growth_saves_a_creature_from_lethal_damage() {
        let mut game = MockGame::builder()
            .hand(Seat::P1, [lightning_bolt()])
            .hand(Seat::P2, [giant_growth()])
            .battlefield(Seat::P2, [grizzly_bears()])
            .mana_pool(Seat::P1, mana![R])
            .mana_pool(Seat::P2, mana![G])
            .build();
        let bolt = game.find(game.p1, HAND, "Lightning Bolt").unwrap();
        let growth = game.find(game.p2, HAND, "Giant Growth").unwrap();
        let bears = game.find(game.p2, BATTLEFIELD, "Grizzly Bears").unwrap();
        let p2 = game.p2;

        game.act(game.p1, actions::Action::Cast(bolt));
        game.act(game.p1, actions::Action::ChooseTargets(vec![bears]));
        game.pass_priority();
        game.act(p2, actions::Action::Cast(growth));
        game.act(p2, actions::Action::ChooseTargets(vec![bears]));
        game.pass_priority_all();
        game.pass_priority_all();

        assert_eq!(game.zone_of(bears), BATTLEFIELD);
        let damage = game.app.world().get::<damage::Damage>(bears).copied();
        assert_eq!(damage, Some(damage::Damage(3)));
        let modifier = game
            .app
            .world()
            .get::<effects::PowerToughnessModifier>(bears)
            .copied();
        assert_eq!(
            modifier,
            Some(effects::PowerToughnessModifier {
                power: 3,
                toughness: 3,
            })
        );
    }
}
